script:
test("weighted credits for 3.7, 3.3 and 2.0 round 3.125 to 3.12", function () {
  var actual = code.calculateGpa({ courses: [
    { gradePoints: "3.7", credits: "3" },
    { gradePoints: "3.3", credits: "3" },
    { gradePoints: "2.0", credits: "2" }
  ] });
  assert.deepEqual(actual, { gpa: "3.12" });
});

test("four one-credit grades round 2.675 half to even to 2.68", function () {
  var actual = code.calculateGpa({ courses: [
    { gradePoints: "4.0", credits: "1" },
    { gradePoints: "3.0", credits: "1" },
    { gradePoints: "2.0", credits: "1" },
    { gradePoints: "1.7", credits: "1" }
  ] });
  assert.deepEqual(actual, { gpa: "2.68" });
});

test("empty course list has no gpa", function () {
  var actual = code.calculateGpa({ courses: [] });
  assert.deepEqual(actual, { gpa: null });
});

test("courses whose credits total zero have no gpa", function () {
  var actual = code.calculateGpa({ courses: [
    { gradePoints: "0", credits: "0" },
    { gradePoints: "0.0", credits: "0.0" }
  ] });
  assert.deepEqual(actual, { gpa: null });
});

test("single course 3.7 on one credit stays 3.70", function () {
  var actual = code.calculateGpa({ courses: [
    { gradePoints: "3.7", credits: "1" }
  ] });
  assert.deepEqual(actual, { gpa: "3.70" });
});

test("halfway 1.225 rounds to even last digit 1.22", function () {
  var actual = code.calculateGpa({ courses: [
    { gradePoints: "1.225", credits: "1" }
  ] });
  assert.deepEqual(actual, { gpa: "1.22" });
});

